from addlib import *
# ---------- TEXTFIELD B14 ----------
e1=tf(L('auth.email'),'diego@',invalid=True,error=L('auth.errors.invalidEmail'),typ='email')
e2=tf(L('auth.email'),'diego@',invalid=True,error=L('auth.errors.invalidEmail'),typ='email',state='is-focus')
add('Textfield',
 block('Decisione · campo in errore: hover e focus',DECI+' '+CONF,'<b>Hover:</b> nessun cambio. Il codice lo fa già: <code>input[aria-invalid="true"]:hover</code> e <code>select[aria-invalid="true"]:hover</code> ripetono lo stesso fondo e bordo di <code>[aria-invalid="true"]</code> (base.less r.222-228), con specificità maggiore del bordo grigio di hover (<code>.on-hover</code> sul campo, r.204). Un campo in errore resta rosso (<code>--danger</code>, bordo interno 2px, fondo al 12%) sotto il puntatore. <b>Focus:</b> anello standard <code>--focus</code> (mai rosso) che abbraccia il campo, con il bordo rosso dell\'errore che resta sotto: l\'errore e il focus si leggono insieme. Il pulsante “cancella” dentro il campo conserva il suo hover (<code>--row-hover</code>).',
  both('360px',f'<div style="display:flex;flex-direction:column;gap:var(--sp-4)">{e1}{e2}</div>','Errore a riposo · errore con focus')+
  pd([
   ['Hover del campo in errore','il canvas non lo mostrava; l\'hover grigio poteva sembrare valido','nessun cambio: resta rosso','base.less r.204, r.222-228'],
   ['Focus del campo in errore','non descritto','anello <code>--focus</code> + bordo rosso sotto','base.less r.206-208'],
  ])))
# ---------- SWITCH B28 ----------
def swd(l,checked,hover=False):
    c=' checked="checked"' if checked else ''
    st=' style="background:var(--primary-hover)"' if (hover and checked) else (' style="background:var(--ink-2)"' if hover else '')
    return (f'<div class="switch"><span>{l}</span><label class="switch__control"><input class="switch__input" type="checkbox" role="switch"{c} aria-label="{l}"/><span class="switch__track" aria-hidden="true"{st}></span></label></div>')
add('Switch e ChoiceGroup',
 block('Decisione · hover sugli interruttori dei filtri',DECI,'Oggi <code>Switch.less</code> non ha nessuno stato di hover (nessuna regola <code>:hover</code> nel file): l\'interruttore sotto il puntatore non reagisce, a differenza di pulsanti e righe. <b>Decisione:</b> hover solo con puntatore fine (<code>.on-hover</code>), transizione <code>--dur-hover</code>: la traccia spenta passa da <code>--disabled</code> a <code>--row-hover</code> e la manopola da <code>--ink-2</code> a <code>--ink</code>; la traccia accesa passa da <code>--accent</code> a <code>--primary-hover</code> (rosso più scuro in chiaro, oro più chiaro in scuro). Nessun movimento (solo colore), quindi nulla da ridurre. Vale per tutti gli interruttori: filtri, account, admin.',
  both('360px',f'<div style="display:flex;flex-direction:column;gap:var(--sp-3)">{swd(L("planner.filters.showAlternate"),False,True)}{swd(L("planner.filters.showUpcoming"),True,True)}</div>','Hover (spento · acceso)')+
  tbl(['Stato','Traccia','Manopola'],[['Riposo spento','<code>--disabled</code>','<code>--ink-2</code>'],['Hover spento','<code>--row-hover</code>','<code>--ink</code>'],['Riposo acceso','<code>--accent</code>','<code>--white</code>'],['Hover acceso','<code>--primary-hover</code>','<code>--white</code>']])+
  pd([['Hover','assente','colore di traccia e manopola, 120 ms, solo puntatore fine','Switch.less r.35-55; mixins.less r.15; tokens.less r.16, r.76']])))
# ---------- SELECT B11 ----------
NAMES=[('de','Deutsch'),('en','English'),('es','Español'),('fr','Français'),('it','Italiano')]
def opt(label,sel=False):
    return f'<div role="option" aria-selected="{"true" if sel else "false"}" data-active="false" class="select-field__option"><span>{label}</span>{icon("check") if sel else ""}</div>'
def inline_open():
    rows=''.join(opt(n,c=='it') for c,n in NAMES)
    return f'<div class="select-field select-field--inline"><span class="select-field__label">{L("nav.language")}</span><button type="button" class="select-field__trigger" aria-haspopup="listbox" aria-expanded="true"><span>Italiano</span>{CHEV}</button><div class="select-field__list" role="listbox" tabindex="-1">{rows}</div></div>'
def after_open():
    rows=''.join(opt(n,c=='it') for c,n in NAMES)
    return f'<div class="select-field select-field--inline" style="position:relative"><span class="select-field__label">{L("nav.language")}</span><button type="button" class="select-field__trigger" aria-haspopup="listbox" aria-expanded="true"><span>Italiano</span>{CHEV}</button><div class="select-field__list" role="listbox" tabindex="-1" style="position:absolute;left:0;right:0;z-index:1;box-shadow:var(--shadow-pop)">{rows}</div></div>'
add('Select',
 block('Decisione · elenco della lingua nel menu mobile',DECI,'Oggi nel pannello del menu la lingua usa <code>layout="inline"</code>: l\'elenco sta nel flusso (<code>margin-top</code>, SelectField.less r.138-145) e spinge giù tema, accesso e il resto: il menu si allunga di cinque righe. <b>Decisione:</b> no. L\'elenco si apre <b>sopra</b> il contenuto (come quello a comparsa, ombra livello 2) con la stessa larghezza del pulsante; l\'altezza del menu non cambia. Il pulsante resta a tutta larghezza con etichetta sopra.',
  '<div class="dc-row">'+phone(f'<div style="padding:var(--sp-4);background:var(--panel);color:var(--on-dark)" class="on-panel">{inline_open()}<div style="height:var(--sp-4)"></div><p>{L("theme.label")}…</p><p>{L("nav.login")}…</p></div>','dark',420,360,'Prima: l\'elenco spinge il resto')
  +phone(f'<div style="padding:var(--sp-4);background:var(--panel);color:var(--on-dark)" class="on-panel">{after_open()}<div style="height:var(--sp-4)"></div><p>{L("theme.label")}…</p><p>{L("nav.login")}…</p></div>','dark',420,360,'Dopo: elenco sopra il contenuto')+'</div>'),
 block('Decisione · scroll con elenco aperto',DECI,'Oggi l\'elenco a comparsa è <code>position: fixed</code> e si riposiziona a ogni scroll di qualsiasi contenitore (<code>window.addEventListener("scroll", position, true)</code>, SelectField.tsx r.136-138): su “Dove guardare”, dentro un pannello che scorre, il riposizionamento resta indietro rispetto al contenitore e l\'elenco sembra staccato. <b>Decisione:</b> <b>si chiude allo scroll</b> della pagina o di un contenitore, tranne che dentro l\'elenco stesso; il focus torna al trigger. È il comportamento dei select nativi su desktop, e toglie il calcolo continuo della posizione. Il ridimensionamento continua a riposizionarlo.',
  tbl(['Evento','Prima','Dopo'],[['Scroll della pagina o di un contenitore','l\'elenco si riposiziona (<code>position</code>)','l\'elenco si chiude (<code>close(false)</code>); il focus resta sul trigger'],['Scroll dentro l\'elenco','scorre l\'elenco (<code>overscroll-behavior: contain</code>)','invariato'],['Resize','si riposiziona','invariato'],['Esc','chiude','invariato']])),
 block('Decisione · margine sotto la voce selezionata',DECI,'Aprendo l\'elenco la voce selezionata viene portata in vista con <code>scrollIntoView({ block: "nearest" })</code> (SelectField.tsx r.145): se è nell\'ultima riga resta a filo del bordo. <b>Decisione:</b> margine di <code>--sp-2</code> sopra e sotto ogni opzione (<code>scroll-margin-block</code> su <code>.select-field__option</code>), così la voce selezionata non tocca mai il bordo. Il rilievo dell\'elenco (<code>max-height: min(320px, 100dvh − 16px)</code>, r.118) non cambia.',
  pd([['Menu mobile, lingua','elenco in linea, allunga il menu','elenco in sovrapposizione','SelectField.less r.138-145; LanguageSwitcher.tsx'],['Scroll con elenco aperto','riposiziona (r.130-134)','chiude','SelectField.tsx r.134-138'],['Voce selezionata a filo','<code>block: "nearest"</code>','+ <code>scroll-margin-block: var(--sp-2)</code> sulle opzioni','SelectField.tsx r.145; SelectField.less (.select-field__option)']])))
# ---------- NAVIGATION B10 B26 ----------
def foot_after():
    cred=L('footer.credits').replace('{justwatch}','<a href="#">JustWatch</a>').replace('{wikipedia}','<a href="#">Wikipedia</a>').replace('{license}',f'<a href="#">{L("footer.creditsLicense")}</a>')
    return (f'<footer class="site-footer on-panel" style="margin-top:0"><div class="site-footer__columns"><div class="site-footer__about"><p class="wordmark wordmark--large">Marvel Planner</p><p class="muted">{L("footer.disclaimer")}</p><p class="muted">{cred}</p></div>'
      f'<div class="site-footer__tmdb" style="align-items:center"><div style="width:96px;height:3rem;border:1px solid var(--line);display:flex;align-items:center;justify-content:center;flex:none" role="img" aria-label="TMDB">TMDB</div><p class="muted">This product uses the TMDB API but is not endorsed or certified by <a href="#">TMDB</a>.</p></div></div>'
      f'<nav class="site-footer__legal" aria-label="{L("footer.legal")}"><a href="#">{L("footer.privacy")}</a>{btn("text",L("footer.privacySettings"))}<span class="site-footer__made" lang="en" style="margin-left:auto;font-family:var(--font-display);font-size:var(--fs-title);letter-spacing:.06em;text-transform:uppercase;color:var(--on-dark)">Made in Italy</span></nav></footer>')
def foot_before():
    return foot_after().replace('style="align-items:center"','').replace('style="margin-left:auto;font-family:var(--font-display);font-size:var(--fs-title);letter-spacing:.06em;text-transform:uppercase;color:var(--on-dark)"','style="margin-left:auto"').replace('class="site-footer__made"','class="site-footer__made muted"').replace(btn("text",L("footer.privacySettings")),btn("text",L("footer.privacySettings"),"","","shield-check"))
add('Navigation',
 block('Decisione · footer: “Made in Italy” e blocco TMDB',DECI,'Oggi “Made in Italy” è una riga <code>muted</code> a destra (<code>.site-footer__made</code>, AppFooter.less) e il blocco TMDB allinea logo e testo in alto (<code>align-items: flex-start</code>, r.40). <b>Decisione:</b> “Made in Italy” in carattere display (Anton, come il logo), maiuscolo, <code>--fs-title</code>, colore <code>--on-dark</code> pieno (non <code>muted</code>), sempre a destra della riga legale; su schermi stretti va a capo e resta a destra. Blocco TMDB: logo e testo <b>centrati in verticale</b> (<code>align-items: center</code>), logo 96px fissi, testo a capo accanto; sotto 40em il logo sopra e il testo sotto, allineati a sinistra. Resta in inglese (<code>lang="en"</code>, testo di licenza richiesto da TMDB). Nelle demo il logo è un riquadro segnaposto.',
  '<div class="dc-row">'+fr('dark','100%',foot_before(),'Prima','0')+fr('dark','100%',foot_after(),'Dopo','0')+'</div>'
  +pd([['“Made in Italy”','<code>muted</code>, corpo del testo','display, <code>--fs-title</code>, <code>--on-dark</code>','AppFooter.less (.site-footer__made); AppFooter.tsx'],['Blocco TMDB','logo e testo in alto','centrati in verticale; sotto 40em in colonna a sinistra','AppFooter.less r.39-57'],['Impostazioni privacy','con icona ShieldCheck','senza icona (regola icone, pagina Buttons)','AppFooter.tsx']])),
 block('Decisione · click sul titolo “MARVEL PLANNER”',DECI,'Oggi il logo (<code>.wordmark</code>, AppHeader.less r.51-57) è un link senza hover né pressione: gli altri controlli hanno entrambi. <b>Decisione:</b> stessa grammatica dei pulsanti: hover con puntatore fine (<code>.on-hover</code>) cambia il colore in <code>--primary-hover</code> in <code>--dur-hover</code> (120 ms); pressione (<code>:active</code>) <code>scale(0.97)</code> in <code>--dur-press</code> (80 ms) solo con <code>prefers-reduced-motion: no-preference</code>; il tocco usa solo la pressione. Il <code>.wordmark--large</code> del footer non è un link e non cambia.',
  tbl(['Stato','Prima','Dopo'],[['Riposo','colore del logo','invariato'],['Hover (puntatore fine)','nessuno','<code>--primary-hover</code>, 120 ms'],['Pressione','nessuna','<code>scale(0.97)</code>, 80 ms (solo movimento normale)'],['Focus da tastiera','anello standard','invariato']])+
  pd([['Logo cliccabile','nessuna animazione','hover colore + pressione','AppHeader.less r.51-57; Button.less r.178 (modello)']])),
)
